/// A gradient picture, as the component gallery draws one.
fn picture(hue: f32) -> ImageData {
    ImageData::from_fn(160, 90, move |x, y| {
        let (u, v) = (x as f32 / 160.0, y as f32 / 90.0);
        Color::rgb(0.2 + 0.6 * u * hue, 0.3 + 0.4 * v, 0.9 - 0.5 * u)
    })
    .unwrap_or_else(|| unreachable!("the size is not zero"))
}

/// The gallery's example of `AspectRatio`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        VStack::new(({
            let mut it = AspectRatio::new(16.0 / 9.0, Image::new(picture(1.0)).stretch());
            it
        },))
        .width(320.0)
        .align(Align::Stretch)
    })
}

impl ComponentBook for AspectRatio<AnyView> {
    fn book() -> Meta {
        Meta::new("Layout/AspectRatio", render)
            .summary("Keeps content at a width-to-height ratio.")
            .story("Example", Args::new())
    }
}
